item.command:
/bin/bash -lc "runuser -u deos-author -- env -i PATH=/usr/local/bin:/usr/bin:/bin HOME=/home/deos-author NODE_EXTRA_CA_CERTS=/etc/cloudflare/certs/cloudflare-containers-ca.crt bash -c 'node - <<'\\''NODE'\\''
const fs = require('\\''fs'\\'');
const scenarios = [
  {
    id: '\\''local-loopback-smoke'\\'', url: '\\''/'\\'', target: '\\''local'\\'', viewport: {width:1440,height:900},
    steps: [
      {operation:'\\''wait'\\'',selector:'\\''#status[data-status=\"error\"]'\\''},
      {operation:'\\''screenshot'\\'',caption:'\\''Sandbox-local Chromium renders the complete one-screen shelf at the loopback origin and visibly reports that its unseeded local storage cannot load; this is local rendering and error-state smoke, not cloud-storage proof.'\\''}
    ]
  },
  {
    id:'\\''remote-empty-shelf'\\'',url:'\\''/'\\'',target:'\\''remote'\\'',viewport:{width:1440,height:900},
    steps:[
      {operation:'\\''wait'\\'',selector:'\\''.empty-card'\\''},
      {operation:'\\''wait'\\'',selector:'\\''#status[data-status=\"idle\"]'\\''},
      {operation:'\\''screenshot'\\'',caption:'\\''The freshly reset remote shelf opens empty with the title field, plain-text editor, saved-title list, reader, and D1 + R2 cloud badge on one screen.'\\''}
    ]
  },
  {
    id:'\\''remote-save-read-refresh-delete'\\'',url:'\\''/'\\'',target:'\\''remote'\\'',viewport:{width:1440,height:900},
    steps:[
      {operation:'\\''wait'\\'',selector:'\\''.empty-card'\\''},
      {operation:'\\''fill'\\'',selector:'\\''#title'\\'',text:'\\''Greeting'\\''},
      {operation:'\\''fill'\\'',selector:'\\''#text'\\'',text:'\\''Hello, team"'!'"'\\''},
      {operation:'\\''click'\\'',selector:'\\''#save-button'\\''},
      {operation:'\\''wait'\\'',selector:'\\''.snippet-item[data-title=\"Greeting\"]'\\''},
      {operation:'\\''fill'\\'',selector:'\\''#title'\\'',text:'\\''Sign-off'\\''},
      {operation:'\\''fill'\\'',selector:'\\''#text'\\'',text:'\\''Kind regards.'\\''},
      {operation:'\\''click'\\'',selector:'\\''#save-button'\\''},
      {operation:'\\''wait'\\'',selector:'\\''.snippet-item[data-title=\"Sign-off\"]'\\''},
      {operation:'\\''click'\\'',selector:'\\''.snippet-item[data-title=\"Sign-off\"] .snippet-title'\\''},
      {operation:'\\''wait'\\'',selector:'\\''#reader[data-reader-state=\"ready\"]'\\''},
      {operation:'\\''screenshot'\\'',caption:'\\''Two snippets are saved on the remote shelf, and selecting Sign-off shows its own Kind regards. body in the reader.'\\''},
      {operation:'\\''navigate'\\'',url:'\\''/'\\''},
      {operation:'\\''wait'\\'',selector:'\\''.snippet-item[data-title=\"Greeting\"]'\\''},
      {operation:'\\''wait'\\'',selector:'\\''.snippet-item[data-title=\"Sign-off\"]'\\''},
      {operation:'\\''click'\\'',selector:'\\''.snippet-item[data-title=\"Greeting\"] .snippet-title'\\''},
      {operation:'\\''wait'\\'',selector:'\\''#reader[data-reader-state=\"ready\"]'\\''},
      {operation:'\\''screenshot'\\'',caption:'\\''After a page reload, both remote titles return and Greeting reads Hello, team"'! from cloud storage.'"'\\''},
      {operation:'\\''click'\\'',selector:'\\''.snippet-item[data-title=\"Sign-off\"] .delete-button'\\''},
      {operation:'\\''wait'\\'',selector:'\\''#status[data-status=\"success\"]'\\''},
      {operation:'\\''screenshot'\\'',caption:'\\''Deleting Sign-off removes only that title; the success message is visible while Greeting remains listed and readable.'\\''}
    ]
  },
  {
    id:'\\''remote-fresh-context-continuity'\\'',url:'\\''/'\\'',target:'\\''remote'\\'',viewport:{width:1440,height:900},
    steps:[
      {operation:'\\''wait'\\'',selector:'\\''.snippet-item[data-title=\"Greeting\"]'\\''},
      {operation:'\\''screenshot'\\'',caption:'\\''A fresh browser context rebuilds the unchanged remote shelf with Greeting present, Sign-off absent, and no reader selection carried over.'\\''},
      {operation:'\\''click'\\'',selector:'\\''.snippet-item[data-title=\"Greeting\"] .snippet-title'\\''},
      {operation:'\\''wait'\\'',selector:'\\''#reader[data-reader-state=\"ready\"]'\\''},
      {operation:'\\''screenshot'\\'',caption:'\\''Selecting Greeting in the fresh context reads Hello, team"'! from the remote D1/R2-backed shelf.'"'\\''}
    ]
  },
  {
    id:'\\''remote-validation-errors'\\'',url:'\\''/'\\'',target:'\\''remote'\\'',viewport:{width:1440,height:900},
    steps:[
      {operation:'\\''wait'\\'',selector:'\\''.snippet-item[data-title=\"Greeting\"]'\\''},
      {operation:'\\''fill'\\'',selector:'\\''#text'\\'',text:'\\''Text without a title'\\''},
      {operation:'\\''click'\\'',selector:'\\''#save-button'\\''},
      {operation:'\\''wait'\\'',selector:'\\''#status[data-status=\"error\"]'\\''},
      {operation:'\\''screenshot'\\'',caption:'\\''Submitting text without a title shows the title-required error while Greeting remains the only saved remote snippet.'\\''},
      {operation:'\\''fill'\\'',selector:'\\''#title'\\'',text:'\\''Empty note'\\''},
      {operation:'\\''fill'\\'',selector:'\\''#text'\\'',text:'\\''   '\\''},
      {operation:'\\''click'\\'',selector:'\\''#save-button'\\''},
      {operation:'\\''screenshot'\\'',caption:'\\''Submitting Empty note with spaces-only text shows the text-required error and leaves the remote shelf unchanged.'\\''}
    ]
  },
  {
    id:'\\''remote-literal-markup'\\'',url:'\\''/'\\'',target:'\\''remote'\\'',viewport:{width:1440,height:900},
    steps:[
      {operation:'\\''wait'\\'',selector:'\\''.snippet-item[data-title=\"Greeting\"]'\\''},
      {operation:'\\''fill'\\'',selector:'\\''#title'\\'',text:'\\''Markup sample'\\''},
      {operation:'\\''fill'\\'',selector:'\\''#text'\\'',text:'\\''<b>Hello</b>'\\''},
      {operation:'\\''click'\\'',selector:'\\''#save-button'\\''},
      {operation:'\\''wait'\\'',selector:'\\''.snippet-item[data-title=\"Markup sample\"]'\\''},
      {operation:'\\''wait'\\'',selector:'\\''#reader[data-reader-state=\"ready\"]'\\''},
      {operation:'\\''screenshot'\\'',caption:'\\''Markup-looking content is shown literally as <b>Hello</b> in the plain-text reader on the remote shelf.'\\''}
    ]
  }
];
const large = '\\''x'\\''.repeat(65536);
const capacitySteps = [
  {operation:'\\''wait'\\'',selector:'\\''.snippet-item[data-title=\"Greeting\"]'\\''},
  {operation:'\\''wait'\\'',selector:'\\''.snippet-item[data-title=\"Markup sample\"]'\\''}
];
for (let i=1;i<=15;i++) {
  const title = "'`Capacity ${String(i).padStart(2,'"'\\''0'\\'')}"'`;
  capacitySteps.push(
    {operation:'"'\\''fill'\\'',selector:'\\''#title'\\'',text:title},
    {operation:'\\''fill'\\'',selector:'\\''#text'\\'',text:large},
    {operation:'\\''click'\\'',selector:'\\''#save-button'\\''},
    {operation:'\\''wait'\\'',selector:"'`.snippet-item[data-title="${title}"]`}
  );
}
capacitySteps.push(
  {operation:'"'\\''fill'\\'',selector:'\\''#title'\\'',text:'\\''Overflow'\\''},
  {operation:'\\''fill'\\'',selector:'\\''#text'\\'',text:large},
  {operation:'\\''click'\\'',selector:'\\''#save-button'\\''},
  {operation:'\\''wait'\\'',selector:'\\''#status[data-status=\"error\"]'\\''},
  {operation:'\\''screenshot'\\'',caption:'\\''A real remote save beyond the approved byte capacity is rejected with a clear no-capacity message, the Overflow form preserved, and no false success state.'\\''}
);
scenarios.push({id:'\\''remote-capacity-failure'\\'',url:'\\''/'\\'',target:'\\''remote'\\'',viewport:{width:1440,height:900},steps:capacitySteps});
fs.writeFileSync('\\''/deos/output/requests/demo-current-final-2.json'\\'',JSON.stringify({action:'\\''demo'\\'',requestId:'\\''demo-current-final-2'\\'',scenarios})+'\\''\\n'\\'');
NODE
wc -c /deos/output/requests/demo-current-final-2.json
deos-implementation --wait /deos/output/requests/demo-current-final-2.json'"
